function Visual({ variant = 'nodes', label = 'SYSTEM MAP' }: { variant?: 'nodes' | 'grid' | 'timeline' | 'lab' | 'contact'; label?: string }) {
  if (variant === 'grid') return <div className="data-grid relative min-h-[270px] overflow-hidden rounded-[1rem] border border-[hsl(var(--border))] bg-[hsl(var(--muted)/.45)]"><div className="absolute inset-[17%] border border-[hsl(var(--primary)/.45)]"><span className="absolute -left-2 -top-2 h-4 w-4 border-l border-t border-[hsl(var(--accent))]" /><span className="absolute -bottom-2 -right-2 h-4 w-4 border-b border-r border-[hsl(var(--accent))]" /></div><div className="absolute left-[23%] top-[39%] h-3 w-3 rounded-full bg-[hsl(var(--primary))] shadow-[0_0_0_7px_hsl(var(--primary)/.13)]" /><div className="absolute right-[25%] top-[30%] h-3 w-3 rounded-full bg-[hsl(var(--accent))] shadow-[0_0_0_7px_hsl(var(--accent)/.13)]" /><div className="absolute bottom-[27%] right-[38%] h-3 w-3 rounded-full bg-[hsl(var(--foreground))]" /><div className="absolute left-[25%] top-[42%] h-px w-[39%] rotate-[-15deg] bg-[hsl(var(--primary)/.55)]" /><p className="absolute bottom-5 left-5 font-mono-ui text-[9px] uppercase tracking-[.18em] text-[hsl(var(--muted-foreground))]">{label} / 03 NODES</p></div>;
  const positions = variant === 'contact' ? [[20, 33], [48, 58], [76, 34]] : [[18, 68], [31, 31], [49, 53], [67, 25], [83, 66]];
  return <div className={`node-field min-h-[270px] rounded-[1rem] border border-[hsl(var(--sidebar-border))] ${variant === 'lab' ? 'rotate-1' : ''}`}><div className="absolute inset-0 opacity-80">{positions.slice(0, -1).map((pos, i) => <span key={i} className="node-line" style={{ left: `${pos[0]}%`, top: `${pos[1]}%`, width: `${Math.abs(positions[i + 1][0] - pos[0]) * 1.15}%`, transform: `rotate(${Math.atan2(positions[i + 1][1] - pos[1], positions[i + 1][0] - pos[0]) * 57.3}deg)` }} />)}</div>{positions.map((pos, i) => <span key={i} className="node" style={{ left: `${pos[0]}%`, top: `${pos[1]}%` }} />)}<div className="absolute bottom-5 left-5 right-5 flex items-center justify-between"><span className="font-mono-ui text-[9px] uppercase tracking-[.18em] text-[hsl(var(--accent))]">{label}</span><span className="font-mono-ui text-[9px] text-[hsl(var(--sidebar-foreground)/.5)]">LIVE / LOCAL</span></div></div>;
}

