function ProjectsPage() {
  useMeta('Projects', 'A curated project workbench of Nkosinathi Ngwenya’s verified AI, software and security repositories.');
  const [filter, setFilter] = useState('All');
  const [query, setQuery] = useState('');
  const filters = ['All', 'AI systems', 'Software', 'Security', 'Private'];
  const filtered = useMemo(() => portfolio.projects.filter((project) => {
    const matchesFilter = filter === 'All' || (filter === 'Private' ? project.visibility === 'Private' : filter === 'AI systems' ? /ai|fraud|aegis/i.test(`${project.name} ${project.kind}`) : filter === 'Security' ? /security|fraud|aegis/i.test(`${project.name} ${project.kind}`) : project.visibility === 'Public');
    return matchesFilter && `${project.name} ${project.kind} ${project.language ?? ''}`.toLowerCase().includes(query.toLowerCase());
  }), [filter, query]);
  return <><PageIntro index="02" eyebrow="project workbench" title={<>Systems, repositories, <span className="text-[hsl(var(--primary))]">in context.</span></>} text="A searchable index of verified work. Open a project for its own route, inspect the source where it is public, or request access to private systems." visual="grid" /><section className="section-wrap pb-24"><div className="mb-8 flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between"><div className="flex flex-wrap gap-2">{filters.map((item) => <button key={item} data-testid={`button-filter-${item}`} onClick={() => setFilter(item)} className={`rounded-full px-3 py-2 font-mono-ui text-[10px] uppercase tracking-[.1em] ${filter === item ? 'bg-[hsl(var(--foreground))] text-[hsl(var(--background))]' : 'border border-[hsl(var(--border))] text-[hsl(var(--muted-foreground))]'}`}>{item}</button>)}</div><label className="flex items-center gap-3 rounded-md border border-[hsl(var(--border))] px-3"><Search size={15} className="text-[hsl(var(--muted-foreground))]"/><input data-testid="input-project-search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search systems..." className="h-11 w-full bg-transparent text-sm outline-none lg:w-64" /></label></div><p className="mb-5 font-mono-ui text-[10px] uppercase tracking-[.1em] text-[hsl(var(--muted-foreground))]">{filtered.length} systems indexed / {filter}</p>{filtered.length ? <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">{filtered.map((project) => <ProjectCard project={project} key={project.id} />)}</div> : <div className="surface-flat rounded-[1rem] p-12 text-center"><Terminal className="mx-auto text-[hsl(var(--primary))]" /><h2 className="mt-4 font-display text-2xl font-semibold">No matching system.</h2><p className="mt-2 text-[hsl(var(--muted-foreground))]">Try another filter or search phrase.</p></div>}</section></>;
}

function ProjectDetailPage() {
  const { id } = useParams<{ id: string }>();
  const [, setLocation] = useLocation();
  const project = portfolio.projects.find((item) => item.id === id);
  const [demoOpen, setDemoOpen] = useState(false);
  if (!project) return <NotFound />;
  useMeta(project.name, `${project.name} — verified project details from Nkosinathi Ngwenya’s portfolio.`);
  const isPrivate = project.visibility === 'Private';
  return <><div className="section-wrap page-enter pb-24 pt-14"><button data-testid="button-project-back" onClick={() => setLocation('/projects')} className="mb-10 inline-flex items-center gap-2 font-mono-ui text-[10px] uppercase tracking-[.12em] text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--primary))]"><ArrowLeft size={14} /> Back to workbench</button><div className="grid gap-12 lg:grid-cols-[1.1fr_.9fr] lg:items-end"><div><div className="flex flex-wrap gap-2"><span className="pill">{isPrivate ? <LockKeyhole size={11} /> : <Globe2 size={11} />}{project.visibility}</span><span className="pill"><Code2 size={11} /> {project.language ?? 'Project system'}</span></div><p className="eyebrow mt-8">{project.kind} / technical deep dive</p><h1 className="display-lg mt-4">{project.name}</h1><p className="mt-7 max-w-2xl text-lg leading-8 text-[hsl(var(--muted-foreground))]">{project.description}</p><div className="mt-8 flex flex-wrap gap-3">{project.github && <a data-testid="link-detail-github" href={project.github} target="_blank" rel="noreferrer" className="btn-primary"><Github size={15} /> View source</a>}{isPrivate && <button data-testid="button-detail-demo" onClick={() => setDemoOpen(true)} className="btn-outline"><Mail size={15} /> Request demo access</button>}</div></div><Visual variant="nodes" label={`PROJECT / ${project.id}`} /></div><div className="mt-20 grid gap-4 md:grid-cols-2"><div className="surface rounded-[1rem] p-7"><p className="eyebrow">Overview</p><h2 className="mt-4 font-display text-2xl font-semibold">What is verified</h2><p className="mt-4 leading-7 text-[hsl(var(--muted-foreground))]">{project.description}</p></div><div className="surface rounded-[1rem] p-7"><p className="eyebrow">Access</p><h2 className="mt-4 font-display text-2xl font-semibold">{isPrivate ? 'Private project' : 'Public repository'}</h2><p className="mt-4 leading-7 text-[hsl(var(--muted-foreground))]">{isPrivate ? 'Source and implementation details are not published. Request demo access for a technical conversation.' : 'The source repository is available from this page. The portfolio does not infer metrics, outcomes or architecture beyond the verified description.'}</p></div>{project.sections?.map((section) => <div key={section.label} className="surface-flat rounded-[1rem] p-7"><p className="eyebrow">{section.label}</p><p className="mt-4 leading-7">{section.text}</p></div>)}</div><div className="mt-16 border-t border-[hsl(var(--border))] pt-7"><p className="font-mono-ui text-[10px] uppercase tracking-[.12em] text-[hsl(var(--muted-foreground))]">Integrity note</p><p className="mt-3 max-w-2xl text-sm leading-6 text-[hsl(var(--muted-foreground))]">Unavailable details remain unavailable. This page intentionally avoids invented problem statements, architecture diagrams, metrics, clients and outcomes.</p></div></div>{demoOpen && <DemoRequestModal project={project} onClose={() => setDemoOpen(false)} />}</>;
}

function CapabilityIcon({ name }: { name: Capability['icon'] }) {
  const icons: Record<Capability['icon'], IconType> = { brain: BrainCircuit, network: Network, radar: Radar, git: Code2, layers: Layers3, shield: ShieldCheck };
  const Icon = icons[name];
  return <Icon size={17} />;
}

function EngineeringPage() {
  useMeta('AI Engineering', 'AI engineering capabilities, skills and security-aware systems by Nkosinathi Ngwenya.');
  const [active, setActive] = useState<string | null>(null);
  return <><PageIntro index="03" eyebrow="AI engineering" title={<>Designing intelligence across <span className="text-[hsl(var(--primary))]">the stack.</span></>} text="A capability map for generative AI, agents, machine learning, infrastructure, evaluation and responsible systems. Labels are intentionally conservative." visual="nodes" /><section className="section-wrap pb-24"><div className="mb-7 flex flex-wrap gap-2"><span className="pill"><span className="status-dot" /> Verified vocabulary</span><span className="pill">Working knowledge</span><span className="pill">Currently exploring</span></div><div className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">{portfolio.capabilities.map((group) => { const open = active === group.title; return <div key={group.title} className={`surface-flat rounded-[.9rem] p-5 transition-colors ${open ? 'border-[hsl(var(--primary))]' : ''}`}><button data-testid={`button-capability-${group.title}`} onClick={() => setActive(open ? null : group.title)} className="flex w-full items-start justify-between text-left focus-ring"><div className="flex gap-3"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-md bg-[hsl(var(--primary)/.1)] text-[hsl(var(--primary))]"><CapabilityIcon name={group.icon} /></span><span><span className="block font-display font-semibold">{group.title}</span><span className="mt-1 block font-mono-ui text-[9px] uppercase tracking-[.1em] text-[hsl(var(--muted-foreground))]">{group.status}</span></span></div><ChevronDown size={16} className={`mt-1 transition-transform ${open ? 'rotate-180' : ''}`} /></button>{open && <div className="mt-5 flex flex-wrap gap-2 border-t border-[hsl(var(--border))] pt-4">{group.items.map((item) => <span key={item} className="rounded-md bg-[hsl(var(--muted))] px-2.5 py-1.5 font-mono-ui text-[10px] text-[hsl(var(--muted-foreground))]">{item}</span>)}</div>}</div>; })}</div><div className="mt-20"><SectionHeading eyebrow="technical index" title="Tools I can name precisely." text="Verified technology vocabulary from the portfolio. No progress bars, no invented proficiency percentages." /><div className="grid gap-px overflow-hidden rounded-[.85rem] border border-[hsl(var(--border))] bg-[hsl(var(--border))] md:grid-cols-2 lg:grid-cols-5">{portfolio.skills.map(([name, values]) => <div key={name} className="bg-[hsl(var(--card))] p-5"><p className="font-mono-ui text-[10px] uppercase tracking-[.1em] text-[hsl(var(--primary))]">{name}</p><div className="mt-4 space-y-2">{values.map((value) => <p key={value} className="font-display text-sm">{value}</p>)}</div></div>)}</div></div><div className="mt-20 rounded-[1.2rem] bg-[hsl(var(--sidebar))] p-7 text-[hsl(var(--sidebar-foreground))] sm:p-10"><div className="grid gap-10 lg:grid-cols-[.8fr_1.2fr]"><div><span className="pill border-[hsl(var(--sidebar-border))] text-[hsl(var(--sidebar-foreground)/.7)]"><ShieldCheck size={12} /> responsible systems</span><h2 className="display-lg mt-6">AI <span className="text-[hsl(var(--accent))]">×</span> security</h2><p className="mt-5 max-w-md leading-7 text-[hsl(var(--sidebar-foreground)/.65)]">Security, privacy, evaluation and failure modes belong in the engineering conversation.</p></div><div className="grid gap-3 sm:grid-cols-2">{['Privacy', 'Reliability', 'Prompt injection awareness', 'Human oversight', 'Evaluation', 'Security'].map((item, i) => <div key={item} className="rounded-lg border border-[hsl(var(--sidebar-border))] p-4"><span className="font-mono-ui text-[10px] text-[hsl(var(--accent))]">0{i + 1}</span><p className="mt-8 font-display">{item}</p></div>)}</div></div></div></section></>;
}

function ArchitecturePage() {
  useMeta('Architecture Explorer', 'A conceptual architecture explorer for thinking about AI application systems.');
  const nodes = [['User', 'Input enters through the product experience.'], ['Application', 'The interface and product layer.'], ['AI orchestrator', 'A conceptual coordination layer.'], ['Retrieval / tools / memory', 'Context and actions when a system uses them.'], ['Model', 'The intelligence layer.'], ['Evaluation', 'Measurement before confidence.'], ['Response', 'The result returned to the user.']];
  const [selected, setSelected] = useState(0);
  return <><PageIntro index="04" eyebrow="architecture explorer" title={<>Follow the path from input to <span className="text-[hsl(var(--primary))]">confidence.</span></>} text="A conceptual AI application flow. Select a node to inspect its role; this is a thinking tool, not a claim about the architecture of any single project." visual="grid" /><section className="section-wrap pb-24"><div className="rounded-[1.2rem] bg-[hsl(var(--sidebar))] p-6 text-[hsl(var(--sidebar-foreground))] sm:p-10"><div className="relative grid gap-3 md:grid-cols-7">{nodes.map(([name], i) => <button key={name} data-testid={`button-architecture-node-${i}`} onClick={() => setSelected(i)} className={`relative z-10 min-h-[130px] rounded-lg border p-4 text-left transition-colors ${selected === i ? 'border-[hsl(var(--accent))] bg-[hsl(var(--accent)/.12)]' : 'border-[hsl(var(--sidebar-border))] bg-[hsl(var(--sidebar-foreground)/.03)] hover:border-[hsl(var(--accent)/.6)]'}`}><span className="font-mono-ui text-[9px] text-[hsl(var(--accent))]">0{i + 1}</span><span className="mt-6 block font-display text-sm font-semibold">{name}</span><span className="mt-2 block text-[10px] text-[hsl(var(--sidebar-foreground)/.5)]">{i === 0 ? 'entry' : i === 6 ? 'output' : 'layer'}</span></button>)}<span className="architecture-line hidden md:block" /></div><div className="mt-8 rounded-[1rem] border border-[hsl(var(--sidebar-border))] bg-[hsl(var(--sidebar-foreground)/.04)] p-6"><span className="eyebrow text-[hsl(var(--accent))]">selected node / 0{selected + 1}</span><h2 className="mt-4 font-display text-2xl">{nodes[selected][0]}</h2><p className="mt-4 max-w-2xl leading-7 text-[hsl(var(--sidebar-foreground)/.65)]">{nodes[selected][1]}</p><p className="mt-8 border-t border-[hsl(var(--sidebar-border))] pt-4 font-mono-ui text-[10px] leading-5 text-[hsl(var(--sidebar-foreground)/.45)]">Conceptual diagram / not a claim about any single project</p></div></div></section></>;
}

function EvaluationPage() {
  useMeta('Evaluation', 'A transparent evaluation interface for responsible AI engineering.');
  const metrics = ['Accuracy', 'Task success', 'Groundedness', 'Retrieval quality', 'Citation accuracy', 'Latency', 'Cost', 'Failure rate'];
  const [selected, setSelected] = useState('Groundedness');
  return <><PageIntro index="05" eyebrow="responsible measurement" title={<>A system is not ready because it <span className="text-[hsl(var(--primary))]">demos well.</span></>} text="A transparent evaluation surface for the measures that matter. Real values appear only when they are available." visual="grid" /><section className="section-wrap pb-24"><div className="surface overflow-hidden rounded-[1rem]"><div className="flex flex-col gap-4 border-b border-[hsl(var(--border))] p-6 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-display font-semibold">Evaluation workspace</p><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">Portfolio-wide view / current state</p></div><span className="flex items-center gap-2 font-mono-ui text-[10px] uppercase tracking-[.1em] text-[hsl(var(--muted-foreground))]"><span className="status-dot bg-[hsl(var(--muted-foreground))] shadow-none" /> Awaiting verified data</span></div><div className="grid gap-px bg-[hsl(var(--border))] sm:grid-cols-2 lg:grid-cols-4">{metrics.map((metric) => <button key={metric} onClick={() => setSelected(metric)} data-testid={`button-evaluation-${metric}`} className={`bg-[hsl(var(--card))] p-5 text-left hover:bg-[hsl(var(--muted))] ${selected === metric ? 'border-l-2 border-[hsl(var(--primary))]' : ''}`}><div className="flex items-center justify-between"><p className="font-mono-ui text-[10px] uppercase tracking-[.08em] text-[hsl(var(--muted-foreground))]">{metric}</p><span className="h-1.5 w-1.5 rounded-full bg-[hsl(var(--border))]" /></div><p className="mt-7 font-display text-lg text-[hsl(var(--muted-foreground))]">No value published</p></button>)}</div></div><div className="mt-5 surface-flat rounded-[1rem] p-6"><p className="eyebrow">Selected measure / {selected}</p><p className="mt-4 max-w-2xl text-sm leading-7 text-[hsl(var(--muted-foreground))]">This portfolio does not publish a value for {selected.toLowerCase()}. The interface keeps the measurement category visible without turning an unavailable result into a fabricated claim.</p></div></section></>;
}

function ExperiencePage() {
  useMeta('Experience', 'Career timeline for Nkosinathi Ngwenya, AI Engineer and Founder & Developer.');
  return <><PageIntro index="06" eyebrow="career timeline" title={<>The roles that shape <span className="text-[hsl(var(--primary))]">the workbench.</span></>} text="A concise career record. Titles, organizations and dates are verified; responsibilities and outcomes are not inferred." visual="timeline" /><section className="section-wrap pb-24"><div className="relative ml-3 border-l border-[hsl(var(--border))] pl-8 sm:ml-10 sm:pl-12">{portfolio.roles.map((role, i) => <article data-testid={`card-experience-${i}`} key={role.company} className="relative mb-5 last:mb-0"><span className="absolute -left-[41px] top-7 h-4 w-4 rounded-full border-4 border-[hsl(var(--background))] bg-[hsl(var(--primary))] sm:-left-[57px]" /><div className="surface rounded-[1rem] p-6 sm:p-8"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><p className="eyebrow">{role.kind}</p><h2 className="mt-3 font-display text-2xl font-semibold">{role.company}</h2><p className="mt-1 text-[hsl(var(--primary))]">{role.title}</p></div><span className="pill">{role.period}</span></div><div className="mt-7 border-t border-[hsl(var(--border))] pt-5"><p className="text-sm leading-6 text-[hsl(var(--muted-foreground))]">Role verified in portfolio record. Additional responsibilities and outcomes are intentionally not stated without source detail.</p></div></div></article>)}</div><div className="mt-16 rounded-[1rem] bg-[hsl(var(--muted)/.6)] p-6 sm:p-8"><p className="eyebrow">Recruiter scan</p><div className="mt-5 flex flex-wrap gap-2">{['AI Engineering', 'Machine Learning', 'Generative AI', 'Full-Stack Engineering', 'Data Engineering', 'Cybersecurity'].map((item) => <span key={item} className="surface-flat rounded-full px-3 py-2 font-mono-ui text-[10px]">{item}</span>)}</div></div></section></>;
}

function LabPage() {
  useMeta('AI Lab', 'Experiments and engineering notes from Nkosinathi Ngwenya’s active research notebook.');
  const topics = ['AI Agents', 'RAG experiments', 'Model evaluation', 'AI reliability', 'AI automation', 'Data experiments', 'Security experiments'];
  const [selected, setSelected] = useState(topics[0]);
  return <><PageIntro index="07" eyebrow="active research notebook" title={<>Experiments, questions, <span className="text-[hsl(var(--primary))]">not theatre.</span></>} text="A research surface for technical explorations. Notes are framed as active work until there is a verified observation worth publishing." visual="lab" /><section className="section-wrap pb-24"><div className="grid gap-4 lg:grid-cols-[.7fr_1.3fr]"><div className="surface-flat rounded-[1rem] p-3">{topics.map((topic, i) => <button data-testid={`button-experiment-${i}`} key={topic} onClick={() => setSelected(topic)} className={`flex w-full items-center justify-between rounded-lg px-4 py-4 text-left ${selected === topic ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'hover:bg-[hsl(var(--muted))]'}`}><span className="flex items-center gap-3"><span className="font-mono-ui text-[10px] opacity-60">0{i + 1}</span><span className="font-display text-sm font-semibold">{topic}</span></span><ChevronRight size={15} /></button>)}</div><div className="surface rounded-[1rem] p-6 sm:p-8"><div className="flex items-center justify-between"><span className="pill"><Sparkles size={11} /> {selected}</span><span className="eyebrow">notebook / active</span></div><div className="mt-8 grid gap-6 sm:grid-cols-2">{[['Question', 'A focused question is being developed for this exploration.'], ['Approach', 'Implementation notes will be added when verified.'], ['Experiment', 'No public result is recorded here.'], ['Observation', 'Results not recorded yet.'], ['Next pass', 'The notebook remains open for future work.']].map(([label, text]) => <div key={label}><p className="font-mono-ui text-[10px] uppercase tracking-[.12em] text-[hsl(var(--primary))]">{label}</p><p className="mt-2 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{text}</p></div>)}</div><div className="mt-8 border-t border-[hsl(var(--border))] pt-5 font-mono-ui text-[10px] text-[hsl(var(--muted-foreground))]">Notebook state / actively maintained, no invented findings</div></div></div><div className="mt-20"><SectionHeading eyebrow="engineering notes" title="Short records from the build loop." text="The notebook is the right home for questions that are still becoming clear."/><div className="grid gap-3 md:grid-cols-2">{['AI agents', 'Model evaluation', 'Security-aware systems', 'From model to product'].map((note) => <article key={note} className="surface-flat rounded-[.9rem] p-5"><span className="pill">Research note</span><h3 className="mt-5 font-display text-lg font-semibold">{note}</h3><p className="mt-2 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Active topic in the engineering notebook; detailed article content is not published.</p></article>)}</div></div></section></>;
}

function AboutPage() {
  useMeta('About', 'Philosophy, journey and engineering direction of Nkosinathi Ngwenya.');
  const principles = [['01', 'Build for reality', 'AI systems should work outside demos.'], ['02', 'Measure before optimizing', 'Performance should be demonstrated, not assumed.'], ['03', 'Simplicity wins', 'Complexity should solve a real problem.'], ['04', 'Security is engineering', 'Failure modes and abuse cases matter.'], ['05', 'Learn by building', 'The strongest learning happens through implementation.']];
  return <><PageIntro index="08" eyebrow="about the engineer" title={<>A human building at the edge of <span className="text-[hsl(var(--primary))]">useful intelligence.</span></>} text="Nkosinathi Ngwenya is an AI Engineer in Hatfield, Pretoria, working across intelligent applications, machine learning, software and security-aware systems." visual="nodes" /><section className="section-wrap pb-24"><div className="grid gap-10 lg:grid-cols-[.75fr_1.25fr]"><div className="surface overflow-hidden rounded-[1rem]"><img src={portrait} alt={portfolio.identity.portraitAlt} className="aspect-[.9] w-full object-cover object-top" /><div className="p-5"><p className="eyebrow">Identity / N 001</p><p className="mt-3 font-display text-xl font-semibold">{portfolio.identity.name}</p><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">{portfolio.identity.location}</p></div></div><div><SectionHeading eyebrow="philosophy" title="How I think." text="A small operating manual for building things that have to survive contact with reality."/><div className="grid gap-px overflow-hidden rounded-[1rem] border border-[hsl(var(--border))] bg-[hsl(var(--border))] sm:grid-cols-2">{principles.map(([number, title, text]) => <div key={number} className="bg-[hsl(var(--card))] p-6"><p className="font-mono-ui text-[10px] text-[hsl(var(--primary))]">{number}</p><h3 className="mt-10 font-display text-xl font-semibold">{title}</h3><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{text}</p></div>)}</div></div></div><div className="mt-20 grid gap-4 md:grid-cols-3"><div className="surface rounded-[1rem] p-6"><p className="eyebrow">Journey</p><p className="mt-6 font-display text-xl font-semibold">From Computer Science foundation to applied AI engineering.</p><Link href="/education" className="mt-7 inline-flex items-center gap-2 font-mono-ui text-[10px] uppercase text-[hsl(var(--primary))]">See education <ArrowRight size={13}/></Link></div><div className="surface rounded-[1rem] p-6"><p className="eyebrow">Current direction</p><p className="mt-6 font-display text-xl font-semibold">Intelligent systems, evaluation and automation.</p><Link href="/lab" className="mt-7 inline-flex items-center gap-2 font-mono-ui text-[10px] uppercase text-[hsl(var(--primary))]">Open lab <ArrowRight size={13}/></Link></div><div className="surface rounded-[1rem] p-6"><p className="eyebrow">AI × security</p><p className="mt-6 font-display text-xl font-semibold">Designing with privacy, reliability and failure modes in mind.</p><Link href="/engineering" className="mt-7 inline-flex items-center gap-2 font-mono-ui text-[10px] uppercase text-[hsl(var(--primary))]">View capabilities <ArrowRight size={13}/></Link></div></div></section></>;
}

function EducationPage() {
  useMeta('Education', 'Academic foundation, modules and credentials for Nkosinathi Ngwenya.');
  const [open, setOpen] = useState<string | null>(null);
  return <><PageIntro index="09" eyebrow="academic foundation" title={<>A degree in systems thinking, <span className="text-[hsl(var(--primary))]">in progress.</span></>} text="BSc Computer Science at the University of Pretoria, with modules spanning programming, algorithms, systems, software modelling and databases." visual="grid" /><section className="section-wrap pb-24"><div className="grid gap-10 lg:grid-cols-[.8fr_1.2fr]"><div><span className="pill"><MapPin size={11} /> Pretoria, South Africa</span><h2 className="mt-6 font-display text-3xl font-semibold">{portfolio.education.degree}</h2><p className="mt-2 text-lg text-[hsl(var(--primary))]">{portfolio.education.institution}</p><p className="mt-2 font-mono-ui text-[10px] text-[hsl(var(--muted-foreground))]">{portfolio.education.period}</p><p className="mt-7 max-w-sm leading-7 text-[hsl(var(--muted-foreground))]">The academic foundation behind a practical interest in intelligent applications, data, software and systems.</p></div><div className="space-y-3">{Object.entries(portfolio.education.modules).map(([title, items]) => { const isOpen = open === title; return <div key={title} className="surface-flat rounded-[.9rem]"><button data-testid={`button-education-${title}`} onClick={() => setOpen(isOpen ? null : title)} className="flex w-full items-center justify-between p-5 text-left"><span><span className="eyebrow">{title}</span><span className="mt-2 block font-display text-lg font-semibold">{items.length} modules indexed</span></span><ChevronDown size={18} className={`transition-transform ${isOpen ? 'rotate-180' : ''}`} /></button>{isOpen && <div className="grid gap-2 border-t border-[hsl(var(--border))] p-5 sm:grid-cols-2">{items.map((item) => <div key={item} className="rounded-md bg-[hsl(var(--muted))] px-3 py-2.5 font-mono-ui text-[10px] leading-5">{item}</div>)}</div>}</div>; })}</div></div><div className="mt-20"><SectionHeading eyebrow="credentials" title="Learning beyond the syllabus." text="Verified certificates and course credentials retained from the portfolio record."/><div className="flex flex-wrap gap-2">{portfolio.certifications.map((item) => <span data-testid={`credential-${item}`} key={item} className="surface-flat rounded-full px-4 py-2.5 font-mono-ui text-[10px]">{item}</span>)}</div></div></section></>;
}

function ContactPage() {
  useMeta('Contact', 'Contact Nkosinathi Ngwenya about AI engineering, intelligent products and technical opportunities.');
  const [form, setForm] = useState({ name: '', email: '', message: '' });
  const [sent, setSent] = useState(false);
  const submit = (event: FormEvent) => { event.preventDefault(); window.location.href = `mailto:${portfolio.identity.email}?subject=${encodeURIComponent(`Portfolio enquiry from ${form.name}`)}&body=${encodeURIComponent(`Email: ${form.email}\n\n${form.message}`)}`; setSent(true); };
  return <><PageIntro index="10" eyebrow="open channel" title={<>Let's build something <span className="text-[hsl(var(--primary))]">useful.</span></>} text="Interested in AI engineering, intelligent products, software systems, collaboration or technical opportunities? Send a clear signal." visual="contact" /><section className="section-wrap pb-24"><div className="grid gap-10 lg:grid-cols-[.8fr_1.2fr]"><div className="space-y-4"><div className="surface rounded-[1rem] p-6"><div className="flex items-center gap-2 font-mono-ui text-[10px] uppercase tracking-[.1em] text-[hsl(var(--primary))]"><span className="status-dot live-dot" /> Open to opportunities</div><div className="mt-8 space-y-4 border-t border-[hsl(var(--border))] pt-5"><p className="flex items-center gap-3 text-sm"><MapPin size={15} className="text-[hsl(var(--primary))]" /> {portfolio.identity.location}</p><a className="flex items-center gap-3 text-sm hover:text-[hsl(var(--primary))]" href={`mailto:${portfolio.identity.email}`}><Mail size={15} className="text-[hsl(var(--primary))]" /> {portfolio.identity.email}</a></div></div><div className="grid gap-2 sm:grid-cols-3"><a href={portfolio.links.linkedin} target="_blank" rel="noreferrer" className="btn-outline"><Linkedin size={15} /> LinkedIn</a><a href={portfolio.links.github} target="_blank" rel="noreferrer" className="btn-outline"><Github size={15} /> GitHub</a><a href={portfolio.links.instagram} target="_blank" rel="noreferrer" className="btn-outline"><ExternalLink size={15} /> Instagram</a></div></div><form onSubmit={submit} className="surface rounded-[1rem] p-6 sm:p-8"><p className="eyebrow">Message relay</p><h2 className="mt-3 font-display text-2xl font-semibold">Start with the problem.</h2><div className="mt-7 space-y-4"><label className="block space-y-2"><span className="eyebrow">Name</span><input data-testid="input-contact-name" required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} className="w-full rounded-md border border-[hsl(var(--border))] bg-transparent px-3 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" /></label><label className="block space-y-2"><span className="eyebrow">Email</span><input data-testid="input-contact-email" required type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} className="w-full rounded-md border border-[hsl(var(--border))] bg-transparent px-3 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" /></label><label className="block space-y-2"><span className="eyebrow">Message</span><textarea data-testid="input-contact-message" required rows={6} value={form.message} onChange={(event) => setForm({ ...form, message: event.target.value })} className="w-full resize-y rounded-md border border-[hsl(var(--border))] bg-transparent px-3 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" /></label><button data-testid="button-submit-contact" type="submit" className="btn-primary w-full sm:w-auto"><Send size={15} /> Prepare email</button>{sent && <p data-testid="status-contact-sent" className="font-mono-ui text-[10px] text-[hsl(var(--primary))]">Email draft prepared in your mail client.</p>}</div></form></div></section></>;
}

function DemoRequestModal({ project, onClose }: { project: Project; onClose: () => void }) {
  const [form, setForm] = useState({ name: '', email: '', organization: '', message: '' });
  const submit = (event: FormEvent) => { event.preventDefault(); window.location.href = `mailto:${portfolio.identity.email}?subject=${encodeURIComponent(`Demo access request: ${project.name}`)}&body=${encodeURIComponent(`Name: ${form.name}\nEmail: ${form.email}\nOrganization: ${form.organization}\nProject requested: ${project.name}\n\n${form.message}`)}`; onClose(); };
  return <div className="modal-backdrop !z-[88]" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><div className="modal-panel" role="dialog" aria-modal="true" aria-labelledby="demo-dialog-title"><div className="flex items-start justify-between border-b border-[hsl(var(--border))] p-6 sm:p-8"><div><span className="eyebrow">Private system / access channel</span><h2 id="demo-dialog-title" className="mt-3 font-display text-3xl font-semibold">Request {project.name}</h2><p className="mt-3 max-w-lg text-sm leading-6 text-[hsl(var(--muted-foreground))]">This prepares an email. Private repositories and credentials are never exposed here.</p></div><button data-testid="button-close-demo-request" onClick={onClose} className="grid h-9 w-9 place-items-center rounded-md border border-[hsl(var(--border))]" aria-label="Close demo request"><X size={16} /></button></div><form onSubmit={submit} className="space-y-4 p-6 sm:p-8"><div className="grid gap-4 sm:grid-cols-2"><label className="space-y-2"><span className="eyebrow">Name</span><input data-testid="input-demo-name" required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} className="w-full rounded-md border border-[hsl(var(--border))] bg-transparent px-3 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" /></label><label className="space-y-2"><span className="eyebrow">Email</span><input data-testid="input-demo-email" required type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} className="w-full rounded-md border border-[hsl(var(--border))] bg-transparent px-3 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" /></label></div><label className="block space-y-2"><span className="eyebrow">Organization</span><input data-testid="input-demo-organization" value={form.organization} onChange={(event) => setForm({ ...form, organization: event.target.value })} className="w-full rounded-md border border-[hsl(var(--border))] bg-transparent px-3 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" /></label><label className="block space-y-2"><span className="eyebrow">Message</span><textarea data-testid="input-demo-message" required rows={4} value={form.message} onChange={(event) => setForm({ ...form, message: event.target.value })} className="w-full resize-y rounded-md border border-[hsl(var(--border))] bg-transparent px-3 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" /></label><div className="flex justify-end gap-3 pt-2"><button data-testid="button-cancel-demo-request" type="button" onClick={onClose} className="btn-outline">Cancel</button><button data-testid="button-send-demo-request" type="submit" className="btn-primary"><Send size={15} /> Prepare request</button></div></form></div></div>;
}

type ChatMessage = { id: number; role: 'user' | 'assistant'; text: string; route?: string | null; projectIds?: string[] };
function AskDrawer({ onClose }: { onClose: () => void }) {
  const [, setLocation] = useLocation();
  const [question, setQuestion] = useState('');
  const [thinking, setThinking] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [lastPrompt, setLastPrompt] = useState('');
  const ask = (prompt: string) => { if (!prompt.trim() || thinking) return; setQuestion(''); setLastPrompt(prompt); setMessages((items) => [...items, { id: Date.now(), role: 'user', text: prompt }]); setThinking(true); window.setTimeout(() => { const result = answerPortfolioQuestion(prompt); setMessages((items) => [...items, { id: Date.now() + 1, role: 'assistant', text: result.text, route: result.route, projectIds: result.projectIds }]); setThinking(false); }, 420); };
  const clear = () => { setMessages([]); setQuestion(''); setLastPrompt(''); };
  const copy = (text: string) => { navigator.clipboard?.writeText(text); };
  return <><div className="modal-backdrop !z-[75]" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }} /><aside className="drawer !z-[76]" aria-label="Ask Nkosinathi's AI"><div className="flex items-start justify-between border-b border-[hsl(var(--border))] p-5 sm:p-7"><div><div className="flex items-center gap-2"><span className="grid h-8 w-8 place-items-center rounded-md bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]"><BrainCircuit size={16} /></span><span className="font-display font-bold">Nkosinathi AI</span></div><p className="mt-3 font-mono-ui text-[10px] uppercase tracking-[.1em] text-[hsl(var(--muted-foreground))]">Verified local knowledge layer</p></div><div className="flex gap-2"><button data-testid="button-clear-ai" onClick={clear} className="grid h-9 w-9 place-items-center rounded-md border border-[hsl(var(--border))]" aria-label="Clear chat"><Trash2 size={14} /></button><button data-testid="button-close-ai" onClick={onClose} className="grid h-9 w-9 place-items-center rounded-md border border-[hsl(var(--border))]" aria-label="Close AI assistant"><X size={16} /></button></div></div><div className="flex min-h-0 flex-1 flex-col p-5 sm:p-7"><div className="max-h-[45dvh] space-y-4 overflow-y-auto pr-1">{messages.length === 0 && <div className="rounded-[.9rem] bg-[hsl(var(--muted))] p-4"><div className="flex items-start gap-3"><span className="mt-1 status-dot" /><p className="text-sm leading-7">Ask about the work, role, education, capabilities or navigation. Answers stay inside the verified portfolio record.</p></div></div>}{messages.map((message) => <div key={message.id} className={message.role === 'user' ? 'ml-8 rounded-[.8rem] bg-[hsl(var(--primary))] p-4 text-sm text-[hsl(var(--primary-foreground))]' : 'rounded-[.8rem] bg-[hsl(var(--muted))] p-4'}><p data-testid={`text-ai-${message.role}-${message.id}`} className="text-sm leading-7">{message.text}</p>{message.role === 'assistant' && <div className="mt-4 flex flex-wrap gap-2">{message.route && <button data-testid="button-ai-navigate" onClick={() => { setLocation(message.route!); onClose(); }} className="inline-flex items-center gap-2 rounded-md bg-[hsl(var(--card))] px-3 py-2 font-mono-ui text-[10px] uppercase tracking-[.08em] text-[hsl(var(--primary))]">Open related page <ArrowRight size={12} /></button>}{message.projectIds?.map((id) => { const project = portfolio.projects.find((item) => item.id === id); return project ? <button key={id} data-testid={`button-ai-project-${id}`} onClick={() => { setLocation(`/projects/${id}`); onClose(); }} className="inline-flex items-center gap-2 rounded-md bg-[hsl(var(--card))] px-3 py-2 font-mono-ui text-[10px] uppercase tracking-[.08em] text-[hsl(var(--primary))]">{project.name} <ArrowRight size={12} /></button> : null; })}<button data-testid={`button-copy-ai-${message.id}`} onClick={() => copy(message.text)} className="inline-flex items-center gap-2 rounded-md border border-[hsl(var(--border))] px-3 py-2 font-mono-ui text-[10px] uppercase tracking-[.08em] text-[hsl(var(--muted-foreground))]"><Copy size={12} /> Copy</button></div>}{message.role === 'assistant' && message.id === messages[messages.length - 1]?.id && lastPrompt && <button data-testid="button-retry-ai" onClick={() => ask(lastPrompt)} className="mt-3 inline-flex items-center gap-2 font-mono-ui text-[10px] uppercase text-[hsl(var(--primary))]"><RotateCcw size={12} /> Retry</button>}</div>)}{thinking && <div data-testid="status-ai-thinking" className="flex items-center gap-3 rounded-[.8rem] bg-[hsl(var(--muted))] p-4 text-sm text-[hsl(var(--muted-foreground))]"><span className="status-dot live-dot" /> Nkosinathi AI is thinking...</div>}</div><div className="mt-auto pt-7"><p className="eyebrow">Suggested questions</p><div className="mt-3 space-y-2">{portfolio.assistant.suggested.slice(0, messages.length ? 3 : 6).map((prompt, i) => <button data-testid={`button-ai-prompt-${i}`} key={prompt} onClick={() => ask(prompt)} className="flex w-full items-center justify-between rounded-md border border-[hsl(var(--border))] px-3 py-3 text-left text-sm hover:border-[hsl(var(--primary))]"><span>{prompt}</span><ChevronRight size={14} className="shrink-0 text-[hsl(var(--muted-foreground))]" /></button>)}</div><form className="mt-6" onSubmit={(event) => { event.preventDefault(); ask(question); }}><label htmlFor="ai-question" className="eyebrow">Ask a verified question</label><div className="mt-3 flex gap-2"><input data-testid="input-ai-question" id="ai-question" value={question} onChange={(event) => setQuestion(event.target.value)} placeholder="Ask about experience, projects..." className="min-w-0 flex-1 rounded-md border border-[hsl(var(--border))] bg-transparent px-3 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" /><button data-testid="button-submit-ai" type="submit" className="grid h-11 w-11 shrink-0 place-items-center rounded-md bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]" aria-label="Ask question"><Send size={15} /></button></div></form></div></div></aside></>;
}

function CommandPalette({ onClose, onAsk }: { onClose: () => void; onAsk: () => void }) {
  const [, setLocation] = useLocation();
  const [query, setQuery] = useState('');
  const commands = useMemo(() => [...navItems.map(([path, label]) => ({ id: path, label: `Open ${label}`, hint: 'Page', action: () => setLocation(path) })), ...portfolio.projects.slice(0, 8).map((project) => ({ id: `project-${project.id}`, label: project.name, hint: project.kind, action: () => setLocation(`/projects/${project.id}`) })), { id: 'ask', label: 'Ask Nkosinathi AI', hint: 'Assistant', action: onAsk }, { id: 'github', label: 'Open GitHub profile', hint: '@NuttyHack', action: () => window.open(portfolio.links.github, '_blank') }], [onAsk, setLocation]);
  const filtered = commands.filter((command) => `${command.label} ${command.hint}`.toLowerCase().includes(query.toLowerCase())).slice(0, 10);
  return <div className="modal-backdrop !z-[90]" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><div className="w-full max-w-xl overflow-hidden rounded-[1rem] border border-[hsl(var(--border))] bg-[hsl(var(--card))] shadow-2xl" role="dialog" aria-modal="true" aria-label="Command palette"><div className="flex items-center gap-3 border-b border-[hsl(var(--border))] px-5"><Search size={17} className="text-[hsl(var(--muted-foreground))]" /><input data-testid="input-command-search" autoFocus value={query} onChange={(event) => setQuery(event.target.value)} onKeyDown={(event) => { if (event.key === 'Escape') onClose(); if (event.key === 'Enter' && filtered[0]) { filtered[0].action(); onClose(); } }} placeholder="Search pages, projects, capabilities..." className="h-16 flex-1 bg-transparent outline-none" /><span className="font-mono-ui text-[9px] text-[hsl(var(--muted-foreground))]">ESC</span></div><div className="max-h-[55vh] overflow-y-auto p-2">{filtered.length ? filtered.map((command) => <button data-testid={`command-${command.id.replace('/', '')}`} key={command.id} onClick={() => { command.action(); onClose(); }} className="flex w-full items-center justify-between rounded-md px-3 py-3 text-left hover:bg-[hsl(var(--muted))]"><span className="flex items-center gap-3"><span className="grid h-7 w-7 place-items-center rounded bg-[hsl(var(--muted))] text-[hsl(var(--primary))]"><ArrowRight size={13} /></span><span className="font-display text-sm">{command.label}</span></span><span className="font-mono-ui text-[9px] uppercase text-[hsl(var(--muted-foreground))]">{command.hint}</span></button>) : <div className="p-8 text-center"><p className="font-display font-semibold">No matching signal.</p><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Try a project, capability or page.</p></div>}</div><div className="flex items-center justify-between border-t border-[hsl(var(--border))] px-5 py-3 font-mono-ui text-[9px] text-[hsl(var(--muted-foreground))]"><span>Portfolio operating system</span><span>↑ ↓ navigate · ↵ open</span></div></div></div>;
}

function RecruiterView({ onClose }: { onClose: () => void }) {
  const [, setLocation] = useLocation();
  return <div className="modal-backdrop !z-[85]"><div className="modal-panel max-w-3xl"><div className="flex items-start justify-between border-b border-[hsl(var(--border))] p-6 sm:p-8"><div><span className="eyebrow">Fast scan / recruiter view</span><h2 className="mt-3 font-display text-3xl font-semibold">{portfolio.identity.name}</h2><p className="mt-2 text-[hsl(var(--primary))]">{portfolio.identity.role}</p></div><button data-testid="button-close-recruiter" onClick={onClose} className="grid h-9 w-9 place-items-center rounded-md border border-[hsl(var(--border))]" aria-label="Close recruiter view"><X size={16} /></button></div><div className="grid gap-8 p-6 sm:p-8 md:grid-cols-[1.1fr_.9fr]"><div>{portfolio.roles.map((role, i) => <div key={role.company} className={i ? 'mt-7' : ''}><p className="eyebrow">{role.kind}</p><p className="mt-3 font-display text-xl font-semibold">{role.company} — {role.title}</p><p className="mt-1 font-mono-ui text-[10px] text-[hsl(var(--muted-foreground))]">{role.period}</p></div>)}</div><div className="surface-flat rounded-[.9rem] p-5"><p className="eyebrow">Education</p><p className="mt-3 font-display font-semibold">{portfolio.education.degree}</p><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">{portfolio.education.institution} · {portfolio.education.period}</p><p className="eyebrow mt-7">Core areas</p><div className="mt-4 flex flex-wrap gap-2">{['AI Engineering', 'Machine Learning', 'Generative AI', 'Full-Stack Engineering', 'Data Engineering', 'Cybersecurity'].map((item) => <span key={item} className="rounded-md bg-[hsl(var(--muted))] px-2.5 py-2 font-mono-ui text-[10px]">{item}</span>)}</div></div></div><div className="flex flex-wrap gap-3 border-t border-[hsl(var(--border))] p-6 sm:p-8"><a data-testid="recruiter-contact" href={`mailto:${portfolio.identity.email}`} className="btn-primary"><Mail size={15} /> Contact</a><a data-testid="recruiter-linkedin" href={portfolio.links.linkedin} target="_blank" rel="noreferrer" className="btn-outline"><Linkedin size={15} /> LinkedIn</a><a data-testid="recruiter-github" href={portfolio.links.github} target="_blank" rel="noreferrer" className="btn-outline"><Github size={15} /> GitHub</a><button data-testid="recruiter-experience" onClick={() => { onClose(); setLocation('/experience'); }} className="btn-quiet">View full experience <ArrowRight size={14} /></button></div></div></div>;
}

function Shell() {
  const [location] = useLocation();
  const [dark, toggleTheme] = useTheme();
  const [askOpen, setAskOpen] = useState(false);
  const [commandOpen, setCommandOpen] = useState(false);
  const [recruiterOpen, setRecruiterOpen] = useState(false);
  useEffect(() => { const handler = (event: KeyboardEvent) => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); setCommandOpen(true); } if (event.key === 'Escape') { setAskOpen(false); setCommandOpen(false); setRecruiterOpen(false); } }; window.addEventListener('keydown', handler); return () => window.removeEventListener('keydown', handler); }, []);
  useEffect(() => { window.scrollTo({ top: 0, behavior: 'smooth' }); }, [location]);
  return <div className="site-shell"><TopNav onAsk={() => setAskOpen(true)} onCommand={() => setCommandOpen(true)} onRecruiter={() => setRecruiterOpen(true)} dark={dark} onTheme={toggleTheme} /><main><Switch><Route path="/" component={() => <Home onAsk={() => setAskOpen(true)} />} /><Route path="/projects" component={ProjectsPage} /><Route path="/projects/:id" component={ProjectDetailPage} /><Route path="/engineering" component={EngineeringPage} /><Route path="/architecture" component={ArchitecturePage} /><Route path="/evaluation" component={EvaluationPage} /><Route path="/experience" component={ExperiencePage} /><Route path="/lab" component={LabPage} /><Route path="/about" component={AboutPage} /><Route path="/education" component={EducationPage} /><Route path="/contact" component={ContactPage} /><Route component={NotFound} /></Switch></main><Footer onAsk={() => setAskOpen(true)} /><button data-testid="button-floating-ai" onClick={() => setAskOpen(true)} className="fixed bottom-5 right-5 z-30 flex items-center gap-2 rounded-full bg-[hsl(var(--foreground))] px-4 py-3 text-[hsl(var(--background))] shadow-xl transition-transform hover:-translate-y-1 focus-ring"><MessageSquareText size={16} /><span className="font-mono-ui text-[10px] uppercase tracking-[.1em]">Ask AI</span></button>{askOpen && <AskDrawer onClose={() => setAskOpen(false)} />}{commandOpen && <CommandPalette onClose={() => setCommandOpen(false)} onAsk={() => setAskOpen(true)} />}{recruiterOpen && <RecruiterView onClose={() => setRecruiterOpen(false)} />}</div>;
}

export default function App() {
  return <Shell />;
}